!function(e){e.behaviors.viewResetScroll={attach:function(e,t){if(e.querySelectorAll('.content-row .view input[id*="edit-reset"]:not([data-view-reset-processed])').forEach((function(e){e.setAttribute("data-view-reset-processed","true"),e.addEventListener("click",(function(t){t.preventDefault();var o=e.closest(".view");if(o){var i=Math.floor(o.getBoundingClientRect().top+window.pageYOffset);setTimeout((function(){window.location=window.location.href.split("?")[0]+"?pos="+i}))}}))})),window.location.search.indexOf("pos=")>-1){var o=new URLSearchParams(window.location.search),i=parseInt(o.get("pos"),10);isNaN(i)||window.scrollTo({top:i,behavior:"auto"})}}}}(Drupal);